// ==============================================================================
// STAGE 2: Algorithmic Heuristic Scoring & Top-K Ranking
// Reduces candidate pairs down to the Top 3 highest-affinity loans per user
// ==============================================================================
const items = $input.all();
const userMap = new Map();

for (const item of items) {
  const row = item.json;
  const userId = row.user_id;

  // Banking Heuristic 1: FOIR 50% Cap -> Maximum Eligible Loan Amount
  const maxEmiCapacity = Number(row.monthly_income) * 0.50;
  const estimatedMaxLoan = Math.min(
    Number(row.max_loan_amount || 4000000),
    Math.round(maxEmiCapacity * 36)
  );

  // Banking Heuristic 2: Suitability Index (0-100)
  // Lowest interest rate + highest income/credit surplus gives maximum score
  const rateScore = Math.max(0, (15 - Number(row.interest_rate)) * 10); // e.g. 10.5% -> 45 pts
  const incomeSurplus = Math.min(30, ((Number(row.monthly_income) - Number(row.min_income)) / Number(row.min_income)) * 20);
  const creditScoreBonus = Math.min(25, ((Number(row.credit_score) - Number(row.min_credit_score)) / 5));
  const totalScore = Math.min(99.9, Math.round((rateScore * 0.45 + incomeSurplus + creditScoreBonus) * 10) / 10);

  const enrichedCandidate = {
    ...row,
    match_score: totalScore,
    max_eligible_loan: estimatedMaxLoan
  };

  if (!userMap.has(userId)) {
    userMap.set(userId, []);
  }
  userMap.get(userId).push(enrichedCandidate);
}

// Keep Top 3 best products for each user
const topMatches = [];
for (const [userId, candidates] of userMap.entries()) {
  candidates.sort((a, b) => b.match_score - a.match_score);
  const topK = candidates.slice(0, 3);
  topMatches.push(...topK);
}

return topMatches.map(m => ({ json: m }));

// ==============================================================================
// STAGE 3: Targeted Qualitative Reasoning Generation
// Generates personalized, professional underwriting narrative for the borrower
// ==============================================================================
const items = $input.all();

return items.map(item => {
  const row = item.json;
  const scoreTier = row.credit_score >= 750 ? 'Prime' : row.credit_score >= 700 ? 'Near-Prime' : 'Standard';

  const reasoning = `Eligible based on ${row.employment_status} status and ${scoreTier} credit profile (${row.credit_score}). Qualifies for ${row.provider_name}'s preferred ${row.interest_rate}% rate with pre-approved borrowing power up to ₹${row.max_eligible_loan.toLocaleString('en-IN')}.`;

  return {
    json: {
      ...row,
      reasoning
    }
  };
});

const items = $input.all();
return {
  summary: `Successfully synchronized and verified ${items.length} institutional loan products.`,
  latest_products: items.map(i => `${i.json.product_name} (${i.json.provider_name}) - ${i.json.interest_rate}%`)
};

// ==============================================================================
// Aggregates offers per user & formats personalized email with test-alias routing
// ==============================================================================
const items = $input.all();
const userOffersMap = new Map();
const testRecipient = 'samarthkolarkar186+one@gmail.com';
const senderEmail = 'samarthkolarkar186@gmail.com';

for (const item of items) {
  const row = item.json;
  const uid = row.user_id;
  if (!userOffersMap.has(uid)) {
    userOffersMap.set(uid, {
      user_id: uid,
      name: row.name,
      original_email: row.email,
      recipient_email: testRecipient,
      match_ids: [],
      products: []
    });
  }

  const uData = userOffersMap.get(uid);
  uData.match_ids.push(row.match_id);
  uData.products.push({
    product_name: row.product_name,
    provider_name: row.provider_name,
    interest_rate: row.interest_rate,
    max_eligible_loan: row.max_eligible_loan,
    reasoning: row.reasoning
  });
}

const emailPayloads = [];
for (const [uid, data] of userOffersMap.entries()) {
  const productsHtml = data.products.map(p => `
    <div style="border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; margin-bottom: 12px; background: #ffffff;">
      <h3 style="margin: 0 0 8px 0; color: #1e293b;">${p.product_name} <span style="font-size: 14px; color: #64748b;">by ${p.provider_name}</span></h3>
      <p style="margin: 4px 0; font-size: 15px; color: #0f172a;"><strong>Interest Rate:</strong> <span style="color: #059669; font-weight: bold;">${p.interest_rate}%</span></p>
      <p style="margin: 4px 0; font-size: 15px; color: #0f172a;"><strong>Pre-Approved Borrowing Power:</strong> ₹${Number(p.max_eligible_loan).toLocaleString('en-IN')}</p>
      <p style="margin: 8px 0 0 0; font-size: 13px; color: #475569; font-style: italic;">${p.reasoning}</p>
    </div>
  `).join('');

  const fullHtml = `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; background: #f8fafc; border-radius: 12px;">
      <div style="background: #0f172a; padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 24px;">
        <h2 style="color: #ffffff; margin: 0;">ClickPe Loan Eligibility Match</h2>
        <p style="color: #94a3b8; margin: 6px 0 0 0; font-size: 14px;">Personalized Personal Loan Offers</p>
      </div>
      <p style="font-size: 16px; color: #334155;">Hello <strong>${data.name}</strong>,</p>
      <p style="font-size: 15px; color: #475569; line-height: 1.5;">Based on your recent financial profile submission, our automated underwriting engine has matched you with the following pre-qualified loan products:</p>
      ${productsHtml}
      <p style="font-size: 12px; color: #94a3b8; margin-top: 24px; text-align: center;">This is a verified test email sent to <code>${data.recipient_email}</code> on behalf of <code>${data.original_email}</code>.</p>
    </div>
  `;

  emailPayloads.push({
    json: {
      user_id: uid,
      to_email: data.recipient_email,
      subject: `🎉 Exclusive Pre-Approved Loan Matches for ${data.name}`,
      html_body: fullHtml,
      match_ids: data.match_ids
    }
  });
}

return emailPayloads.slice(0, 2);
